	public static int GetAtlasIdByStringId(string theStringId)
	{
		for (int i = 0; i < table.Length; i++)
		{
			if (theStringId == table[i].mStringId)
			{
				return table[i].mImageId;
			}
		}
		return (int)Resources.GetIdByStringId(theStringId);
	}

